package com.create.nautilus.content.submarine;
import com.create.nautilus.registry.NautilusBlockEntityTypes; import com.simibubi.create.content.kinetics.base.HorizontalKineticBlock; import com.simibubi.create.foundation.block.IBE; import net.minecraft.core.*; import net.minecraft.world.InteractionResult; import net.minecraft.world.entity.player.Player; import net.minecraft.world.level.*; import net.minecraft.world.level.block.entity.BlockEntityType; import net.minecraft.world.level.block.state.BlockState; import net.minecraft.world.phys.BlockHitResult;
public final class BallastTankControllerBlock extends HorizontalKineticBlock implements IBE<BallastTankControllerBlockEntity>{public BallastTankControllerBlock(Properties p){super(p);} public Direction.Axis getRotationAxis(BlockState s){return Direction.Axis.Y;} public boolean hasShaftTowards(LevelReader l,BlockPos p,BlockState s,Direction f){return f==Direction.DOWN;} public Class<BallastTankControllerBlockEntity> getBlockEntityClass(){return BallastTankControllerBlockEntity.class;} public BlockEntityType<? extends BallastTankControllerBlockEntity> getBlockEntityType(){return NautilusBlockEntityTypes.BALLAST_TANK_CONTROLLER.get();} @Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide)withBlockEntityDo(l,p,be->pl.openMenu(be,p));return InteractionResult.sidedSuccess(l.isClientSide);}}
